T="$TMPDIR/i043"; python3 - <<'PYEOF'
import re, os, subprocess

defs = []
with open(os.environ['TMPDIR']+'/i043/tasklet_defs.txt') as f:
    for line in f:
        m = re.match(r'\./(.+):(\d+):', line.strip())
        if m:
            defs.append((m.group(1), int(m.group(2))))

results = []
for path, start in defs:
    try:
        with open(path, errors='replace') as f:
            lines = f.readlines()
    except Exception:
        continue
    # find function end: line with only '}' at col 0
    end = min(start-1+400, len(lines))
    depth_end = None
    for i in range(start-1, end):
        if lines[i].rstrip().endswith('}') and (lines[i].startswith('}') or lines[i].rstrip() == '}'):
            depth_end = i+1
            break
    if depth_end is None:
        depth_end = min(start-1+120, len(lines))
    body = lines[start-1:depth_end]
    lockvars = set()
    for ln in body:
        for m in re.finditer(r'spin_lock(?:_irqsave|_irq|_bh|_nested)?\s*\(\s*&?\s*([^,)]+)', ln):
            lockvars.add(m.group(1).strip())
    # also read_lock variants
    if lockvars:
        results.append((path, start, depth_end, sorted(lockvars)))

with open(os.environ['TMPDIR']+'/i043/tasklet_locks.txt','w') as out:
    for path, s, e, lv in sorted(results):
        out.write(f"{path}:{s}-{e} :: {'; '.join(lv)}\n")
print(len(results), "tasklet bodies with spinlock acquisitions")
PYEOF
head -80 "$TMPDIR/i043/tasklet_locks.txt"

T="$TMPDIR/i043"; python3 - <<'PYEOF'
import re, os, subprocess
env = os.environ['TMPDIR']
env2 = dict(os.environ, LC_ALL='C')

defs = []
with open(env+'/i043/tasklet_defs.txt') as f:
    for line in f:
        m = re.match(r'\./(.+):(\d+):', line.strip())
        if m:
            defs.append((m.group(1), int(m.group(2))))

results = []
plain_re = re.compile(r'\bspin_lock\s*\(')
lock_re = re.compile(r'spin_lock\s*\(\s*&?\s*([^,)]+)')
for path, start in defs:
    try:
        with open(path, errors='replace') as f:
            lines = f.readlines()
    except Exception:
        continue
    end = None
    for i in range(start-1, min(start-1+400, len(lines))):
        t = lines[i].rstrip()
        if t == '}':
            end = i+1
            break
    if end is None:
        end = min(start-1+120, len(lines))
    body = lines[start-1:end]
    for idx, ln in enumerate(body):
        if plain_re.search(ln):
            m = lock_re.search(ln)
            lv = m.group(1).strip() if m else '?'
            results.append((path, start+idx, lv, ln.strip()[:100]))

with open(env+'/i043/tasklet_plain.txt','w') as out:
    for path, ln, lv, src in sorted(results):
        out.write(f"{path}:{ln} :: {lv} :: {src}\n")
print(len(results), "plain spin_lock sites inside tasklet bodies")
PYEOF
cat "$TMPDIR/i043/tasklet_plain.txt"

